from PIL import Image
im = Image.open("/tmp/toundra/letter-r.png").convert("RGB")
w,h = im.size
px = im.load()
def is_ink(x,y):
    r,g,b = px[x,y]
    return r+g+b < 450
def is_lime(x,y):
    r,g,b = px[x,y]
    return g>180 and r>140 and b<100

# counter bbox
cxs=[]; cys=[]
for y in range(h):
    for x in range(w):
        if is_lime(x,y) and 40<x<470 and 140<y<700:
            # only interior: neighbor ink somewhere? just collect and we'll see
            cxs.append(x); cys.append(y)
print("lime interior-ish", min(cxs), max(cxs), min(cys), max(cys), "count", len(cxs))

# Find the notch between legs: lime gap near bottom center
print("--- horizontal lime gaps ---")
for y in range(140, 820, 30):
    gaps=[]; on=False
    for x in range(10, w-10):
        if is_lime(x,y) and not on:
            on=True; s=x
        elif not is_lime(x,y) and on:
            on=False
            if s>20 and x<w-20:
                gaps.append((s, x-1, x-s))
    if gaps:
        print(y, gaps)

# right edge profile: max ink x per y band
print("--- right silhouette every 40px ---")
for y in range(132, 812, 40):
    xs=[x for x in range(w) if is_ink(x,y)]
    if xs:
        print(f"y={y} x0={min(xs)} x1={max(xs)} width={max(xs)-min(xs)}")
