def xml_text(text: str) -> str:
    text = text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

    def soften(match: re.Match[str]) -> str:
        # Break long URLs on slashes. A missing zero-width glyph draws a box.
        url = match.group(0)
        pieces = url.split("/")
        lines: list[str] = []
        current = pieces[0]
        for piece in pieces[1:]:
            addition = "/" + piece
            if len(current) + len(addition) > 58 and current:
                lines.append(current)
                current = addition
            else:
                current += addition
        if current:
            lines.append(current)
        return "<br/>".join(lines)

    text = re.sub(r"https?://[^\s<]+", soften, text)
    text = re.sub(r"\*\*([^*]+)\*\*", r"<b>\1</b>", text)
    return text

